INSERT INTO exercises (id, external_id, name, slug, description, category, body_part, equipment, target_muscle, secondary_muscles, difficulty, exercise_type, instructions, benefits, precautions, is_active) VALUES ('a1545c65-e273-56ce-b5f3-e19bbb5ebaf1', '0001', '3/4 sit-up', 'three-quarter-sit-up', '3/4 sit-up is a intermediate calisthenics movement targeting the core & abs.', 'Hypertrophy', 'waist', 'Bodyweight', 'Core & Abs', '{"Hip Flexors","Lower Back"}'::text[], 'intermediate', 'calisthenics', '{"Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or crossed over your chest.","Contract your abs to lift your torso about 3/4 of the way up toward your knees.","Pause for a moment at the top of the movement.","Slowly lower back down to the starting position."}'::text[], '{"Targets and develops the core & abs.","Builds functional movement capacity using bodyweight."}'::text[], '{"Perform a thorough dynamic warm-up prior to high-intensity sets.","Maintain spinal neutrality and discontinue set if sharp joint pain occurs."}'::text[], true) ON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, target_muscle = EXCLUDED.target_muscle, equipment = EXCLUDED.equipment, updated_at = now();
INSERT INTO exercise_instructions (exercise_id, language_code, instruction_steps) VALUES ('a1545c65-e273-56ce-b5f3-e19bbb5ebaf1', 'en', '[{"step": 1, "text": "Lie flat on your back with your knees bent and feet flat on the ground."}, {"step": 2, "text": "Place your hands behind your head or crossed over your chest."}, {"step": 3, "text": "Contract your abs to lift your torso about 3/4 of the way up toward your knees."}, {"step": 4, "text": "Pause for a moment at the top of the movement."}, {"step": 5, "text": "Slowly lower back down to the starting position."}]'::jsonb) ON CONFLICT (exercise_id, language_code) DO UPDATE SET instruction_steps = EXCLUDED.instruction_steps, updated_at = now();
INSERT INTO exercise_media (exercise_id, media_type, url, thumbnail_url, width, height, source, license, attribution, is_primary) VALUES ('a1545c65-e273-56ce-b5f3-e19bbb5ebaf1', 'gif', 'https://cdn.example.com/exercises/0001.gif', NULL, 720, 720, 'hasaneyldrm/exercises-dataset', 'Unlicensed-Third-Party-Placeholder', 'Third-party reference asset from openGym/exercises-dataset. Explicitly flagged for in-house replacement before commercial release.', true);
