INSERT INTO exercises (id, external_id, name, slug, description, category, body_part, equipment, target_muscle, secondary_muscles, difficulty, exercise_type, instructions, benefits, precautions, is_active) VALUES ('0b4a8fc8-46c7-51ee-96bd-ca5fb7ff9624', '0043', 'barbell full squat', 'barbell-full-squat', 'barbell full squat is a intermediate strength movement targeting the quadriceps.', 'Strength', 'upper legs', 'Barbell', 'Quadriceps', '{"Glutes","Hamstrings","Calves","Lower Back"}'::text[], 'intermediate', 'strength', '{"Rest the barbell on your upper back traps and step back from the rack.","Position your feet shoulder-width apart, toes pointing slightly outward.","Inhale and brace your core.","Bend your knees and hips, sitting back as if into a chair.","Descend until your hips are below parallel with your knees.","Drive through your heels to return to standing position."}'::text[], '{"Targets and develops the quadriceps.","Builds functional movement capacity using barbell."}'::text[], '{"Perform a thorough dynamic warm-up prior to high-intensity sets.","Maintain spinal neutrality and discontinue set if sharp joint pain occurs."}'::text[], true) ON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, target_muscle = EXCLUDED.target_muscle, equipment = EXCLUDED.equipment, updated_at = now();
INSERT INTO exercise_instructions (exercise_id, language_code, instruction_steps) VALUES ('0b4a8fc8-46c7-51ee-96bd-ca5fb7ff9624', 'en', '[{"step": 1, "text": "Rest the barbell on your upper back traps and step back from the rack."}, {"step": 2, "text": "Position your feet shoulder-width apart, toes pointing slightly outward."}, {"step": 3, "text": "Inhale and brace your core."}, {"step": 4, "text": "Bend your knees and hips, sitting back as if into a chair."}, {"step": 5, "text": "Descend until your hips are below parallel with your knees."}, {"step": 6, "text": "Drive through your heels to return to standing position."}]'::jsonb) ON CONFLICT (exercise_id, language_code) DO UPDATE SET instruction_steps = EXCLUDED.instruction_steps, updated_at = now();
INSERT INTO exercise_media (exercise_id, media_type, url, thumbnail_url, width, height, source, license, attribution, is_primary) VALUES ('0b4a8fc8-46c7-51ee-96bd-ca5fb7ff9624', 'gif', 'https://cdn.example.com/exercises/0043.gif', NULL, 720, 720, 'hasaneyldrm/exercises-dataset', 'Unlicensed-Third-Party-Placeholder', 'Third-party reference asset from openGym/exercises-dataset. Explicitly flagged for in-house replacement before commercial release.', true);
