INSERT INTO exercise_ai_config (exercise_id, pose_detection_supported, rep_counting_supported, form_analysis_supported, required_keypoints, optional_keypoints, movement_phases, angle_rules, distance_rules, form_rules, common_mistakes, correction_messages, minimum_confidence) VALUES ('0b4a8fc8-46c7-51ee-96bd-ca5fb7ff9624', true, true, true, '["LEFT_HIP", "RIGHT_HIP", "LEFT_KNEE", "RIGHT_KNEE", "LEFT_ANKLE", "RIGHT_ANKLE"]'::jsonb, '["LEFT_SHOULDER", "RIGHT_SHOULDER"]'::jsonb, '["start", "down", "bottom_hold", "up", "complete"]'::jsonb, '{"knee": {"down": {"min": 70, "max": 105}, "up": {"min": 160, "max": 180}}, "hip": {"down": {"min": 65, "max": 95}, "up": {"min": 165, "max": 180}}}'::jsonb, '{"knee_lateral_displacement_tolerance": 0.08}'::jsonb, '{"depth_check": "hip_crease_below_patella", "torso_lean_max_deg": 45, "heel_contact_required": true}'::jsonb, '[{"code": "insufficient_depth", "name": "Incomplete Depth", "penalty": 20}, {"code": "knee_valgus", "name": "Knees Caving Inward", "penalty": 25}, {"code": "heel_lift", "name": "Heel Rising", "penalty": 15}]'::jsonb, '{"insufficient_depth": "Squat lower until thighs are parallel to ground.", "knee_valgus": "Drive knees outward over your middle toes.", "heel_lift": "Keep your weight balanced across your whole foot."}'::jsonb, 0.7) ON CONFLICT (exercise_id) DO UPDATE SET angle_rules = EXCLUDED.angle_rules, form_rules = EXCLUDED.form_rules, updated_at = now();
INSERT INTO exercises (id, external_id, name, slug, description, category, body_part, equipment, target_muscle, secondary_muscles, difficulty, exercise_type, instructions, benefits, precautions, is_active) VALUES ('2fc1a5af-5d53-5578-897e-b9005f144338', '0662', 'push-up', 'push-up', 'push-up is a intermediate calisthenics movement targeting the chest.', 'Strength', 'chest', 'Bodyweight', 'Chest', '{"Triceps","Shoulders","Core & Abs"}'::text[], 'intermediate', 'calisthenics', '{"Place hands firmly on the ground, shoulder-width apart.","Ground your toes into the lower floor to stabilize your lower half.","Lower your chest down until it nearly touches the floor.","Keep your back flat and core engaged throughout.","Exhale and push back up to the plank starting position."}'::text[], '{"Targets and develops the chest.","Builds functional movement capacity using bodyweight."}'::text[], '{"Perform a thorough dynamic warm-up prior to high-intensity sets.","Maintain spinal neutrality and discontinue set if sharp joint pain occurs."}'::text[], true) ON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, target_muscle = EXCLUDED.target_muscle, equipment = EXCLUDED.equipment, updated_at = now();
INSERT INTO exercise_instructions (exercise_id, language_code, instruction_steps) VALUES ('2fc1a5af-5d53-5578-897e-b9005f144338', 'en', '[{"step": 1, "text": "Place hands firmly on the ground, shoulder-width apart."}, {"step": 2, "text": "Ground your toes into the lower floor to stabilize your lower half."}, {"step": 3, "text": "Lower your chest down until it nearly touches the floor."}, {"step": 4, "text": "Keep your back flat and core engaged throughout."}, {"step": 5, "text": "Exhale and push back up to the plank starting position."}]'::jsonb) ON CONFLICT (exercise_id, language_code) DO UPDATE SET instruction_steps = EXCLUDED.instruction_steps, updated_at = now();
INSERT INTO exercise_media (exercise_id, media_type, url, thumbnail_url, width, height, source, license, attribution, is_primary) VALUES ('2fc1a5af-5d53-5578-897e-b9005f144338', 'gif', 'https://cdn.example.com/exercises/0662.gif', NULL, 720, 720, 'hasaneyldrm/exercises-dataset', 'Unlicensed-Third-Party-Placeholder', 'Third-party reference asset from openGym/exercises-dataset. Explicitly flagged for in-house replacement before commercial release.', true);
