INSERT INTO exercise_ai_config (exercise_id, pose_detection_supported, rep_counting_supported, form_analysis_supported, required_keypoints, optional_keypoints, movement_phases, angle_rules, distance_rules, form_rules, common_mistakes, correction_messages, minimum_confidence) VALUES ('2fc1a5af-5d53-5578-897e-b9005f144338', true, true, true, '["LEFT_SHOULDER", "RIGHT_SHOULDER", "LEFT_ELBOW", "RIGHT_ELBOW", "LEFT_WRIST", "RIGHT_WRIST", "LEFT_HIP", "LEFT_ANKLE"]'::jsonb, '["NOSE", "RIGHT_HIP", "RIGHT_ANKLE"]'::jsonb, '["plank_start", "eccentric_lowering", "chest_contact", "concentric_press", "lockout"]'::jsonb, '{"elbow": {"bottom": {"min": 75, "max": 95}, "top": {"min": 160, "max": 180}}, "trunk_alignment_deg": {"max_deviation": 12}}'::jsonb, '{"chest_to_ground_cm_max": 12}'::jsonb, '{"hip_sag_permitted": false, "scapular_winging_tolerance": 0.15}'::jsonb, '[{"code": "partial_rom", "name": "Half Reps", "penalty": 20}, {"code": "hip_sag", "name": "Lumbar Sagging", "penalty": 30}, {"code": "elbow_flare", "name": "Flared Elbows", "penalty": 15}]'::jsonb, '{"partial_rom": "Lower chest all the way to floor height.", "hip_sag": "Tighten your core and glutes to maintain straight plank line.", "elbow_flare": "Tuck elbows at 45 degrees relative to ribs."}'::jsonb, 0.68) ON CONFLICT (exercise_id) DO UPDATE SET angle_rules = EXCLUDED.angle_rules, form_rules = EXCLUDED.form_rules, updated_at = now();
INSERT INTO exercises (id, external_id, name, slug, description, category, body_part, equipment, target_muscle, secondary_muscles, difficulty, exercise_type, instructions, benefits, precautions, is_active) VALUES ('e72b53c5-d0bb-5e6b-ba3e-2a3b7578d3d3', '0032', 'barbell deadlift', 'barbell-deadlift', 'barbell deadlift is a intermediate strength movement targeting the glutes.', 'Strength', 'back', 'Barbell', 'Glutes', '{"Hamstrings","Lower Back","Lats","Upper Back & Traps","Forearms"}'::text[], 'intermediate', 'strength', '{"Stand with mid-foot under the barbell.","Bend over and grab the bar with a shoulder-width grip.","Bend your knees until your shins touch the bar.","Lift your chest up and straighten your lower back.","Take a big breath, hold it, and stand up with the weight.","Hold the weight for a second at the top, with locked hips and knees."}'::text[], '{"Targets and develops the glutes.","Builds functional movement capacity using barbell."}'::text[], '{"Perform a thorough dynamic warm-up prior to high-intensity sets.","Maintain spinal neutrality and discontinue set if sharp joint pain occurs."}'::text[], true) ON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, target_muscle = EXCLUDED.target_muscle, equipment = EXCLUDED.equipment, updated_at = now();
INSERT INTO exercise_instructions (exercise_id, language_code, instruction_steps) VALUES ('e72b53c5-d0bb-5e6b-ba3e-2a3b7578d3d3', 'en', '[{"step": 1, "text": "Stand with mid-foot under the barbell."}, {"step": 2, "text": "Bend over and grab the bar with a shoulder-width grip."}, {"step": 3, "text": "Bend your knees until your shins touch the bar."}, {"step": 4, "text": "Lift your chest up and straighten your lower back."}, {"step": 5, "text": "Take a big breath, hold it, and stand up with the weight."}, {"step": 6, "text": "Hold the weight for a second at the top, with locked hips and knees."}]'::jsonb) ON CONFLICT (exercise_id, language_code) DO UPDATE SET instruction_steps = EXCLUDED.instruction_steps, updated_at = now();
INSERT INTO exercise_media (exercise_id, media_type, url, thumbnail_url, width, height, source, license, attribution, is_primary) VALUES ('e72b53c5-d0bb-5e6b-ba3e-2a3b7578d3d3', 'gif', 'https://cdn.example.com/exercises/0032.gif', NULL, 720, 720, 'hasaneyldrm/exercises-dataset', 'Unlicensed-Third-Party-Placeholder', 'Third-party reference asset from openGym/exercises-dataset. Explicitly flagged for in-house replacement before commercial release.', true);
