INSERT INTO exercise_ai_config (exercise_id, pose_detection_supported, rep_counting_supported, form_analysis_supported, required_keypoints, optional_keypoints, movement_phases, angle_rules, distance_rules, form_rules, common_mistakes, correction_messages, minimum_confidence) VALUES ('e72b53c5-d0bb-5e6b-ba3e-2a3b7578d3d3', true, true, true, '["LEFT_SHOULDER", "LEFT_HIP", "LEFT_KNEE", "LEFT_ANKLE", "RIGHT_SHOULDER", "RIGHT_HIP", "RIGHT_KNEE", "RIGHT_ANKLE"]'::jsonb, '["LEFT_WRIST", "RIGHT_WRIST"]'::jsonb, '["setup_grip", "liftoff_drive", "lockout", "eccentric_hinge", "floor_reset"]'::jsonb, '{"hip": {"lockout": {"min": 170, "max": 180}}, "knee": {"lockout": {"min": 170, "max": 180}}}'::jsonb, '{"bar_path_horizontal_drift_max_cm": 8}'::jsonb, '{"spinal_flexion_permitted": false, "hyperextension_permitted": false}'::jsonb, '[{"code": "rounded_back", "name": "Spinal Flexion (Back Rounding)", "penalty": 35}, {"code": "hyperextension", "name": "Excessive Leanback Lockout", "penalty": 20}, {"code": "hitching", "name": "Ramping on Thighs", "penalty": 15}]'::jsonb, '{"rounded_back": "Lock lats and keep chest proud to maintain a flat back.", "hyperextension": "Stand tall at lockout without leaning back.", "hitching": "Pull smoothly without resting bar on thighs."}'::jsonb, 0.72) ON CONFLICT (exercise_id) DO UPDATE SET angle_rules = EXCLUDED.angle_rules, form_rules = EXCLUDED.form_rules, updated_at = now();
INSERT INTO exercises (id, external_id, name, slug, description, category, body_part, equipment, target_muscle, secondary_muscles, difficulty, exercise_type, instructions, benefits, precautions, is_active) VALUES ('8ed02621-379d-5014-b591-f80dc106dfa9', '0294', 'dumbbell bicep curl', 'dumbbell-bicep-curl', 'dumbbell bicep curl is a intermediate strength movement targeting the biceps.', 'Hypertrophy', 'upper arms', 'Dumbbell', 'Biceps', '{"Forearms","Brachialis"}'::text[], 'intermediate', 'strength', '{"Stand tall holding a dumbbell in each hand at arm''s length.","Keep your elbows close to your torso and rotate palms facing forward.","Curl the weights while contracting your biceps as you breathe out.","Continue until your biceps are fully contracted and dumbbells are at shoulder level.","Slowly begin to bring the dumbbells back to starting position as your breathe in."}'::text[], '{"Targets and develops the biceps.","Builds functional movement capacity using dumbbell."}'::text[], '{"Perform a thorough dynamic warm-up prior to high-intensity sets.","Maintain spinal neutrality and discontinue set if sharp joint pain occurs."}'::text[], true) ON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, target_muscle = EXCLUDED.target_muscle, equipment = EXCLUDED.equipment, updated_at = now();
INSERT INTO exercise_instructions (exercise_id, language_code, instruction_steps) VALUES ('8ed02621-379d-5014-b591-f80dc106dfa9', 'en', '[{"step": 1, "text": "Stand tall holding a dumbbell in each hand at arm''s length."}, {"step": 2, "text": "Keep your elbows close to your torso and rotate palms facing forward."}, {"step": 3, "text": "Curl the weights while contracting your biceps as you breathe out."}, {"step": 4, "text": "Continue until your biceps are fully contracted and dumbbells are at shoulder level."}, {"step": 5, "text": "Slowly begin to bring the dumbbells back to starting position as your breathe in."}]'::jsonb) ON CONFLICT (exercise_id, language_code) DO UPDATE SET instruction_steps = EXCLUDED.instruction_steps, updated_at = now();
