INSERT INTO exercise_ai_config (exercise_id, pose_detection_supported, rep_counting_supported, form_analysis_supported, required_keypoints, optional_keypoints, movement_phases, angle_rules, distance_rules, form_rules, common_mistakes, correction_messages, minimum_confidence) VALUES ('8ed02621-379d-5014-b591-f80dc106dfa9', true, true, true, '["LEFT_SHOULDER", "LEFT_ELBOW", "LEFT_WRIST", "RIGHT_SHOULDER", "RIGHT_ELBOW", "RIGHT_WRIST"]'::jsonb, '["LEFT_HIP", "RIGHT_HIP"]'::jsonb, '["start_hang", "concentric_curl", "peak_squeeze", "eccentric_lower", "complete"]'::jsonb, '{"elbow": {"bottom": {"min": 155, "max": 180}, "peak": {"min": 40, "max": 70}}}'::jsonb, '{"elbow_drift_horizontal_max_cm": 7}'::jsonb, '{"torso_swinging_permitted": false}'::jsonb, '[{"code": "torso_swing", "name": "Using Momentum / Body Swing", "penalty": 25}, {"code": "elbow_drift", "name": "Elbows Drifting Forward", "penalty": 15}]'::jsonb, '{"torso_swing": "Keep your torso still; initiate movement strictly from arms.", "elbow_drift": "Pin your elbows firmly by your sides."}'::jsonb, 0.65) ON CONFLICT (exercise_id) DO UPDATE SET angle_rules = EXCLUDED.angle_rules, form_rules = EXCLUDED.form_rules, updated_at = now();
